                    }
                    let side = side.normalize() * half;
                    let lift = to.normalize_or_zero() * half * 2.0;
                    let col = if va.color[3] < 200 && vb.color[3] < 200 { cs } else { cn };
                    let base = verts.len() as u16;
                    for p in [a - side + lift, a + side + lift, b + side + lift, b - side + lift] {
