                    }
                    idx.extend_from_slice(&[base, base + 1, base + 2, base, base + 2, base + 3]);
                    if verts.len() >= 31996 {
                        flush(&mut verts, &mut idx);
                    }
                }
                n += 1;
                if n > 60000 {
                    break 'all;
                }
            }
        }
    }
    flush(&mut verts, &mut idx);
}

